import { CSSProperties } from 'react';

import {
  StyledCardsContainer,
  StyledCardsContainerSubtitle,
  StyledCardsContainerTitle,
  StyledCardsContainerTitleText,
  StyledIcon,
  StyledWrapper,
} from './CardsContainer.styles';

interface CardsContainerProps {
  title?: string;
  subtitle?: string;
  icon?: string;
  children: React.ReactNode;
  variant?: string;
  style?: CSSProperties;
  titleSize?: 'xl' | 'lg';
}

export const CardsContainer = ({
  title,
  subtitle,
  icon,
  children,
  style,
  variant = 'default',
  titleSize = 'lg',
}: CardsContainerProps) => {
  return (
    <StyledCardsContainer variant={variant} style={style}>
      <StyledCardsContainerTitle>
        {icon && <StyledIcon src={icon} alt={title} titleSize={titleSize} />}
        <StyledCardsContainerTitleText titleSize={titleSize}>
          {title}
        </StyledCardsContainerTitleText>
      </StyledCardsContainerTitle>
      {subtitle && (
        <StyledCardsContainerSubtitle>{subtitle}</StyledCardsContainerSubtitle>
      )}
      <StyledWrapper>{children}</StyledWrapper>
    </StyledCardsContainer>
  );
};
